                pg.on('pageerror', lambda e: errs.append(tag + ' ' + str(e)))
                pg.on('console', lambda m: errs.append(tag + ' console ' + m.text + ' @ ' + str((m.location or {}).get('url', ''))[:160]) if m.type == 'error' and 'realtime' not in m.text and 'WebSocket' not in m.text and '404' not in m.text else None)
